public class CourtServiceImpl implements CourtService {

    private final CourtRepository courtRepository;

    public CourtServiceImpl(CourtRepository courtRepository) {
        this.courtRepository = courtRepository;
    }

    @Override
    public boolean isValidCourt(IsValidCourtRequest isValidCourtRequest) {
        CourtFileNumber courtFileNumber = isValidCourtRequest.getCourtFileNumber();
        CourtDetails courtDetails = courtRepository.getCourtDetails(courtFileNumber);

        if (courtDetails == null) {
            return false;
        }

        return isValidCourtRequest.isValidCourt(courtDetails);
    }

