Object getFieldValue(Component component, String fieldName) throws Exception {
        Field field = getField(component, fieldName);
        if (field == null) {
            throw new Exception("Field not found");
        }
        return field.get(component);
    }

    private Field getField(Component component, String fieldName) throws Exception {
        Class<?> componentClass = component.getClass();
        for (Field field : componentClass.getDeclaredFields()) {
            if (field.isAnnotationPresent(FileSize.class) || field.isAnnotationPresent(Duration.class)) {
                return field;
            }
        }
        throw new Exception("Field not found with annotation");
    }
}

