import java.util.List;

public class ParamInjector {

    public static <T> void inject(List<T> params, Object instance) {
        for (T param : params) {
            if (param instanceof Constructor) {
                try {
                    Class<?> clazz = param.getClass();
                    Constructor<?> ctor = clazz.getConstructor();
                    ctor.setAccessible(true);
                    instance = ctor.newInstance();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            } else if (param instanceof Method) {
                try {
                    Class<?> clazz = param.getClass();
                    Method method = clazz.getMethod("set" + Character.toUpperCase((char) ('A' + method.getName().indexOf('A'))), params.getClass());
                    method.setAccessible(true);
                    method.invoke(instance, param);
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

