    public void storeEvent(String eventId, String eventData) {
        Session session = cluster.connect();
        try {
            String serializedEventData = objectMapper.writeValueAsString(eventData);
            session.execute("INSERT INTO events (id, data) VALUES (?, ?)", eventId, serializedEventData);
        } catch (Exception e) {
            throw new RuntimeException(e);
        } finally {
            session.close();
        }
    }

