    public static void shuffleList(IntList list, Random rand) {
        int[] values = list.getValues();
        for (int i = 0; i < values.length; i++) {
            int index = rand.nextInt(values.length);
            int temp = values[i];
            values[i] = values[index];
            values[index] = temp;
